function inverter(texto) {
  let invertido = "";
  for (const letra of texto) {
    invertido = letra + invertido;
  }
  return invertido;
}

function ehPalindromo(frase) {
  const limpa = frase.toLowerCase().replaceAll(" ", "");
  return limpa === inverter(limpa);
}

