js12m4.solucao:
function rolarDado(lados) {
  if (!Number.isInteger(lados) || lados < 2) {
    return null;
  }
  return Math.floor(Math.random() * lados) + 1;
}

function resumo(rolagens) {
  const maior = Math.max(...rolagens);
  const menor = Math.min(...rolagens);
  const soma = rolagens.reduce((total, valor) => total + valor, 0);
  const media = Math.round((soma / rolagens.length) * 10) / 10;
  return { maior, menor, media };
}

const rolagens = [rolarDado(20), rolarDado(20), rolarDado(20)];
console.log(rolagens);
console.log(resumo(rolagens));

