js12m5.solucao:
const MS_POR_DIA = 1000 * 60 * 60 * 24;

function diasEntre(inicio, fim) {
  return Math.round((fim - inicio) / MS_POR_DIA);
}

function aviso(hoje, copa) {
  const dias = diasEntre(hoje, copa);
  if (dias > 0) {
    return `Faltam ${dias} dias para a Copa Pixel (${copa.toLocaleDateString("pt-BR")}).`;
  }
  if (dias === 0) {
    return "A Copa Pixel é hoje!";
  }
  return "A Copa Pixel já terminou.";
}

const hoje = new Date(2025, 2, 10);
const copa = new Date(2025, 3, 2);
console.log(diasEntre(hoje, copa));
console.log(aviso(hoje, copa));

