const PARTIDAS = [
  { jogador: "  ana SOUZA ", inicio: new Date(2025, 2, 8, 14, 0), fim: new Date(2025, 2, 8, 14, 32), pontos: 1250 },
  { jogador: "léo martins", inicio: new Date(2025, 2, 9, 20, 15), fim: new Date(2025, 2, 9, 21, 22), pontos: 980 },
  { jogador: "BIA", inicio: new Date(2025, 2, 10, 9, 5), fim: new Date(2025, 2, 10, 9, 45), pontos: 1116 },
];

function formatarNome(nome) {
  return nome
    .trim()
    .toLowerCase()
    .split(" ")
    .map((palavra) => palavra.at(0).toUpperCase() + palavra.slice(1))
    .join(" ");
}

function minutosDeJogo(partida) {
  return Math.round((partida.fim - partida.inicio) / 60000);
}

function formatarDuracao(minutos) {
  if (minutos < 60) {
    return `${minutos}min`;
  }
  const horas = Math.floor(minutos / 60);
  const resto = String(minutos % 60).padStart(2, "0");
  return `${horas}h${resto}min`;
}

function linhaDaPartida(partida) {
  const data = partida.inicio.toLocaleDateString("pt-BR");
  const nome = formatarNome(partida.jogador);
  const duracao = formatarDuracao(minutosDeJogo(partida));
  const pontos = partida.pontos.toLocaleString("pt-BR");
  return `${data} | ${nome} | ${duracao} | ${pontos} pontos`;
}

function relatorio(partidas) {
  const linhas = [];
  let totalMinutos = 0;
  let totalPontos = 0;
  for (const partida of partidas) {
    linhas.push(linhaDaPartida(partida));
    totalMinutos += minutosDeJogo(partida);
    totalPontos += partida.pontos;
  }
  const media = totalPontos / partidas.length;
  linhas.push(`Partidas: ${partidas.length} | Tempo total: ${formatarDuracao(totalMinutos)}`);
  linhas.push(`Média: ${media.toLocaleString("pt-BR", { maximumFractionDigits: 1 })} pontos por partida`);
  return linhas;
}

for (const linha of relatorio(PARTIDAS)) {
  console.log(linha);
}

